function f = HS17_f(x)
f = (1 - x(1)).^2 + 100*(-x(1).^2 + x(2)).^2;
end

function g = HS17_g(x)
g = zeros(2, 1);
g(1) = -400*x(1).*(-x(1).^2 + x(2)) + 2*x(1) - 2;
g(2) = -200*x(1).^2 + 200*x(2);
end

function c = HS17_c(x)
c = zeros(2, 1);
c(1) = -x(1) + x(2).^2;
c(2) = x(1).^2 - x(2);
end

function J = HS17_J(x)
J = zeros(2, 2);
J(1, 1) = -1;
J(1, 2) = 2*x(2);
J(2, 1) = 2*x(1);
J(2, 2) = -1;
end
